async function eligible(){
 if(eligibility!==null)return eligibility;
 if(!["GTK","KEPALA_SEKOLAH"].includes(String(profile().role||""))){eligibility=false;return false}
 const {data,error}=await sb.from("ks_bcks_submission_details").select("workflow_stage,admin_status,is_archived").eq("user_id",profile().id).maybeSingle();
 eligibility=!error&&!!data&&!data.is_archived&&["SUBSTANSI","DIKLAT","SERTIFIKAT"].includes(data.workflow_stage)&&["TERVERIFIKASI","DISETUJUI"].includes(data.admin_status);
 return eligibility;
}
function placeCard(body,d){
 const first=body.firstElementChild;
 if(first)first.insertAdjacentElement("afterend",d);else body.prepend(d);
}
function scheduleInject(){
 if(reinjectQueued)return;
 reinjectQueued=true;
 setTimeout(()=>{reinjectQueued=false;injectCard()},60);
}
async function setAccessFromKabid(open){
 const label=open?"membuka":"menutup";
 if(!confirm("Yakin ingin "+label+" akses Simulasi dan Thinking Culture untuk peserta KS?"))return null;
 const result=await api({action:"set_access",open});
 $("bcksSubstansiSimulatorCard")?.remove();
 await injectCard();
 return result;
}
async function injectCard(){
 if(injectInFlight)return;
 const body=$("diklatKsBcksBody");
 if(!body)return;

 const existing=[...document.querySelectorAll("#bcksSubstansiSimulatorCard")];
 if(existing.length){
  existing.slice(1).forEach(el=>el.remove());
  return;
 }

 injectInFlight=true;
 try{
  const role=String(profile().role||"");
  const isDinas=String(profile().account_channel||"").toUpperCase()==="DINAS";

  if(LEADER.has(role)&&isDinas){
   const access=await accessStatus();
   if(document.querySelector("#bcksSubstansiSimulatorCard"))return;
   const d=document.createElement("div");d.id="bcksSubstansiSimulatorCard";d.className="bsub-card";
   const status=access.is_open?"DIBUKA":"DITUTUP";
   const statusStyle=access.is_open?"color:#177245":"color:#a44528";
   d.innerHTML='<h3>🧠 Dashboard Simulasi dan Thinking Culture</h3><div class="bsub-note">Monitoring agregat Simulasi dan Thinking Culture peserta BCKS. Nilai di modul ini merupakan indikator latihan SIMANTAB, bukan passing grade resmi Kemendikdasmen.</div><div class="bsub-note" style="margin-top:8px">'+sessionNote+'</div><div class="bsub-note" style="margin-top:8px"><b>Akses peserta KS: <span style="'+statusStyle+'">'+status+'</span></b></div><div class="bsub-actions"><button class="bsub-btn" id="bcksOpenLeader">Lihat Peta Kesiapan</button>'+(access.can_manage?'<button class="bsub-btn '+(access.is_open?'warn':'')+'" id="bcksToggleAccessCard">'+(access.is_open?'Tutup Akses Simulasi':'Buka Akses Simulasi')+'</button>':'')+'</div>';
   placeCard(body,d);
   $("bcksOpenLeader").onclick=openLeader;
   if(access.can_manage&&$("bcksToggleAccessCard"))$("bcksToggleAccessCard").onclick=async()=>{try{await setAccessFromKabid(!access.is_open)}catch(e){alert(e.message||e)}};
   return;
  }

  if(!(await eligible()))return;
  const access=await accessStatus();
  if(document.querySelector("#bcksSubstansiSimulatorCard"))return;

  const d=document.createElement("div");d.id="bcksSubstansiSimulatorCard";d.className="bsub-card";
  if(!access.is_open){
   d.innerHTML='<h3>🔒 Simulasi dan Thinking Culture & AI Coach</h3><div class="bsub-note"><b>Akses simulasi belum tersedia pada jadwal atau ditutup Kabid.</b><br>Jadwal: 3, 7, dan 10 Oktober 2026, pukul 09.00–15.00 WIB. Modul mengikuti jadwal dan kendali akses Kabid. Peserta belum dapat memulai simulasi atau AI Coach.<br>'+sessionNote+'</div><div class="bsub-actions"><button class="bsub-btn" disabled>Menunggu Jadwal / Akses Kabid</button></div>';
   placeCard(body,d);return;
  }

  d.innerHTML='<h3>🎯 Simulasi dan Thinking Culture & AI Coach</h3><div class="bsub-note"><b>3 sesi × 70 soal berbeda • 120 menit per sesi • SJT berbasis kasus.</b> Empat opsi dirancang sama-sama masuk akal; pilih tindakan yang paling tepat. Setelah simulasi, sistem memetakan Kepribadian, Sosial, Manajerial, Kewirausahaan, dan Supervisi, lalu memberi latihan adaptif sesuai kompetensi pada area terlemah.<br><b>Catatan:</b> ini latihan SIMANTAB, bukan ujian resmi dan bukan passing grade Kemendikdasmen.</div><div class="bsub-note">'+sessionNote+'</div><div class="bsub-actions"><button class="bsub-btn" id="bcksOpenParticipant">Buka Modul Latihan</button></div>';
  placeCard(body,d);
  $("bcksOpenParticipant").onclick=openHome;
 } finally {
  injectInFlight=false;
  const dup=[...document.querySelectorAll("#bcksSubstansiSimulatorCard")];
  dup.slice(1).forEach(el=>el.remove());
 }
}
function installObserver(){
 if(observer)return;
 observer=new MutationObserver(()=>scheduleInject());
 observer.observe(document.body,{childList:true,subtree:true});
 scheduleInject();
}
